import { types } from "node:util";

export const MIST_RAVEN_POLICY = "awa_mist_raven_v1" as const;
export interface AlchemistState {
  policy: typeof MIST_RAVEN_POLICY;
  mistRemaining: 0 | 1;
  healRemaining: 0 | 1;
  mistHistory: Array<{ day: number; targetIds: number[] | null }>;
  healHistory: Array<{ day: number; targetId: number | null }>;
}
export interface RavenState {
  policy: typeof MIST_RAVEN_POLICY;
  awakenedDay: number | null;
  knownTeammateIds: number[];
  extraRemaining: 0 | 1;
  extraHistory: Array<{ day: number; targetId: number | null }>;
}
function record(value: unknown, keys: readonly string[]): Record<string, unknown> | undefined {
  if (!value || typeof value !== "object" || types.isProxy(value) || Array.isArray(value)) return;
  const descriptors: Record<string, PropertyDescriptor> = Object.getOwnPropertyDescriptors(
    value as object,
  );
  if (Reflect.ownKeys(descriptors).length !== keys.length) return;
  const result: Record<string, unknown> = {};
  for (const key of keys) {
    const d = descriptors[key];
    if (!d || !("value" in d)) return;
    result[key] = d.value;
  }
  return result;
}
function items(value: unknown): unknown[] | undefined {
  if (types.isProxy(value) || !Array.isArray(value)) return;
  const descriptors: Record<string, PropertyDescriptor> = Object.getOwnPropertyDescriptors(
    value as object,
  );
  const length: unknown = descriptors.length?.value;
  if (
    typeof length !== "number" ||
    !Number.isSafeInteger(length) ||
    length < 0 ||
    Reflect.ownKeys(descriptors).length !== length + 1
  )
    return;
  const out: unknown[] = [];
  for (let n = 0; n < length; n++) {
    const d = descriptors[String(n)];
    if (!d || !("value" in d)) return;
    out.push(d.value);
  }
  return out;
}
function positive(value: unknown): value is number {
  return (
    typeof value === "number" &&
    Number.isSafeInteger(value) &&
    value > 0 &&
    value < Number.MAX_SAFE_INTEGER
  );
}
function ids(value: unknown): number[] | undefined {
  const list = items(value);
  return list && list.every(positive) && new Set(list).size === list.length ? list : undefined;
}
function pointHistory(
  value: unknown,
  earliest: number,
): Array<{ day: number; targetId: number | null }> | undefined {
  const list = items(value);
  if (!list) return;
  const out: Array<{ day: number; targetId: number | null }> = [];
  let last = earliest - 1,
    spent = false;
  for (const item of list) {
    const r = record(item, ["day", "targetId"]);
    if (
      !r ||
      !positive(r.day) ||
      r.day <= last ||
      spent ||
      (r.targetId !== null && !positive(r.targetId))
    )
      return;
    out.push({ day: r.day, targetId: r.targetId as number | null });
    last = r.day;
    spent ||= r.targetId !== null;
  }
  return out;
}
export function createAlchemistState(): AlchemistState {
  return {
    policy: MIST_RAVEN_POLICY,
    mistRemaining: 1,
    healRemaining: 1,
    mistHistory: [],
    healHistory: [],
  };
}
export function readAlchemistState(value: unknown): AlchemistState | undefined {
  const r = record(value, [
    "policy",
    "mistRemaining",
    "healRemaining",
    "mistHistory",
    "healHistory",
  ]);
  if (!r || r.policy !== MIST_RAVEN_POLICY) return;
  const choices = items(r.mistHistory),
    heals = pointHistory(r.healHistory, 1);
  if (!choices || !heals) return;
  let last = 0,
    spent = false;
  const mistHistory: AlchemistState["mistHistory"] = [];
  for (const item of choices) {
    const c = record(item, ["day", "targetIds"]);
    if (!c || !positive(c.day) || c.day <= last || spent) return;
    const targets = c.targetIds === null ? null : ids(c.targetIds);
    if (targets !== null && (!targets || targets.length !== 3)) return;
    mistHistory.push({ day: c.day, targetIds: targets! });
    last = c.day;
    spent ||= targets !== null;
  }
  const mistRemaining = spent ? 0 : 1,
    healRemaining = heals.some((h) => h.targetId !== null) ? 0 : 1;
  if (r.mistRemaining !== mistRemaining || r.healRemaining !== healRemaining) return;
  return {
    policy: MIST_RAVEN_POLICY,
    mistRemaining,
    healRemaining,
    mistHistory,
    healHistory: heals,
  };
}
export function selectMist(
  state: AlchemistState,
  day: number,
  targetIds: number[] | null,
  livingIds: readonly number[],
): AlchemistState {
  const next = readAlchemistState(state),
    targets = targetIds === null ? null : ids(targetIds);
  if (
    !next ||
    next.mistRemaining !== 1 ||
    !positive(day) ||
    day <= (next.mistHistory.at(-1)?.day ?? 0)
  )
    throw new Error("mist_choice_unavailable");
  if (
    targets !== null &&
    (!targets || targets.length !== 3 || targets.some((id) => !livingIds.includes(id)))
  )
    throw new Error("mist_choice_target_invalid");
  next.mistHistory.push({ day, targetIds: targets! });
  if (targets !== null) next.mistRemaining = 0;
  return next;
}
/** Legal targets already embody the pending night's original knife, life and self-heal rule. */
export function selectSnake(
  state: AlchemistState,
  day: number,
  targetId: number | null,
  legalTargets: readonly number[],
): AlchemistState {
  const next = readAlchemistState(state);
  if (
    !next ||
    next.healRemaining !== 1 ||
    !positive(day) ||
    day <= (next.healHistory.at(-1)?.day ?? 0)
  )
    throw new Error("snake_choice_unavailable");
  if (targetId !== null && (!positive(targetId) || !legalTargets.includes(targetId)))
    throw new Error("snake_choice_target_invalid");
  next.healHistory.push({ day, targetId });
  if (targetId !== null) next.healRemaining = 0;
  return next;
}
export function createRavenState(): RavenState {
  return {
    policy: MIST_RAVEN_POLICY,
    awakenedDay: null,
    knownTeammateIds: [],
    extraRemaining: 1,
    extraHistory: [],
  };
}
export function readRavenState(value: unknown): RavenState | undefined {
  const r = record(value, [
    "policy",
    "awakenedDay",
    "knownTeammateIds",
    "extraRemaining",
    "extraHistory",
  ]);
  if (!r || r.policy !== MIST_RAVEN_POLICY || (r.awakenedDay !== null && !positive(r.awakenedDay)))
    return;
  const known = ids(r.knownTeammateIds),
    history = pointHistory(r.extraHistory, (r.awakenedDay as number | null) ?? 1);
  if (
    !known ||
    known.length > 1 ||
    !history ||
    (r.awakenedDay === null && (known.length > 0 || history.length > 0))
  )
    return;
  const remaining = history.some((h) => h.targetId !== null) ? 0 : 1;
  if (r.extraRemaining !== remaining) return;
  return {
    policy: MIST_RAVEN_POLICY,
    awakenedDay: r.awakenedDay as number | null,
    knownTeammateIds: known,
    extraRemaining: remaining,
    extraHistory: history,
  };
}
/** Called once by the actual night-start owner, never by a query or daytime change. */
export function unsealRaven(
  state: RavenState,
  day: number,
  actorId: number,
  livingWolfIds: readonly number[],
): RavenState {
  const next = readRavenState(state);
  if (
    !next ||
    !positive(day) ||
    !positive(actorId) ||
    next.knownTeammateIds.includes(actorId) ||
    !livingWolfIds.includes(actorId) ||
    livingWolfIds.some((id) => !positive(id)) ||
    new Set(livingWolfIds).size !== livingWolfIds.length
  )
    throw new Error("raven_unseal_invalid");
  if (next.awakenedDay !== null) {
    if (day < next.awakenedDay) throw new Error("raven_unseal_invalid");
    return next;
  }
  if (livingWolfIds.length < 3) {
    next.awakenedDay = day;
    next.knownTeammateIds = livingWolfIds.filter((id) => id !== actorId).sort((a, b) => a - b);
  }
  return next;
}
export function selectRavenKnife(
  state: RavenState,
  day: number,
  actorId: number,
  targetId: number | null,
  livingIds: readonly number[],
): RavenState {
  const next = readRavenState(state);
  if (
    !next ||
    !positive(actorId) ||
    next.knownTeammateIds.includes(actorId) ||
    next.awakenedDay === null ||
    next.extraRemaining !== 1 ||
    !positive(day) ||
    day < next.awakenedDay ||
    day <= (next.extraHistory.at(-1)?.day ?? 0) ||
    !livingIds.includes(actorId)
  )
    throw new Error("raven_knife_unavailable");
  if (
    targetId !== null &&
    (!positive(targetId) || targetId === actorId || !livingIds.includes(targetId))
  )
    throw new Error("raven_knife_target_invalid");
  next.extraHistory.push({ day, targetId });
  if (targetId !== null) next.extraRemaining = 0;
  return next;
}

/**
 * Owns Mist/Raven caster state bindings and audited mist, Snake and Raven knife writes. Inputs
 * are original role/life/state data; outputs are checked stock updates and committed effects
 * only while the captured caster matches. Stale or closed caster authority fails without
 * installing a replacement state.
 */
import { types } from "node:util";
import { COMPONENT } from "../../../../core/domain/components/names";
import {
  aliveLifeDescriptor,
  aliveLifeVersion,
  type AliveComponent,
} from "../../../../core/domain/components/alive";
import type { RoleComponent } from "../../../../core/domain/components/role";
import { Camp } from "../../../../core/domain/identity";
import type { World } from "../../../../core/domain/world";
import {
  readAlchemistState,
  readRavenState,
  selectMist,
  selectSnake,
  selectRavenKnife,
  unsealRaven,
  type AlchemistState,
  type RavenState,
} from "./state";

type Caster = "alchemist" | "raven_claw_wolf";
type State = AlchemistState | RavenState;
function own(value: unknown, key: PropertyKey): unknown {
  if (!value || typeof value !== "object" || types.isProxy(value)) return undefined;
  const d = Object.getOwnPropertyDescriptor(value, key);
  return d && "value" in d ? d.value : undefined;
}
interface StateBinding {
  raw: State;
  expected: string;
  arrays: Array<{ key: string; value: unknown; rows: unknown[]; nestedTargets?: unknown[] }>;
}

/** Per-night caster state authority. The enclosing night owner supplies day, targets and phase scope. */
export class MistCasterAuthority {
  private readonly role: RoleComponent;
  private readonly privateState: RoleComponent["privateState"];
  private readonly identity: unknown;
  private readonly identityFields: unknown[];
  private readonly life: AliveComponent;
  private readonly lifeVersion: number;
  private readonly camp: Camp;
  private readonly campComponent: unknown;
  private readonly key: "alchemist" | "ravenClaw";
  private binding: StateBinding;
  private ravenChecked = false;

  constructor(
    private readonly world: World,
    readonly actorId: number,
    readonly day: number,
    readonly caster: Caster,
  ) {
    if (
      !Number.isSafeInteger(day) ||
      day < 1 ||
      day >= Number.MAX_SAFE_INTEGER ||
      !Number.isSafeInteger(actorId) ||
      actorId < 1 ||
      actorId >= Number.MAX_SAFE_INTEGER ||
      (caster !== "alchemist" && caster !== "raven_claw_wolf")
    )
      throw new Error("mist_caster_authority_invalid");
    const role = world.getComponent(actorId, COMPONENT.Role),
      campComponent = world.getComponent(actorId, COMPONENT.Camp),
      identity = world.getComponent(actorId, COMPONENT.Identity),
      life = world.getComponent(actorId, COMPONENT.Alive);
    this.camp = caster === "alchemist" ? Camp.Good : Camp.Wolf;
    this.key = caster === "alchemist" ? "alchemist" : "ravenClaw";
    if (
      !role ||
      own(role, "role") !== caster ||
      own(role, "camp") !== this.camp ||
      own(campComponent, "camp") !== this.camp ||
      !life ||
      !this.factoryLife(life) ||
      !life.alive ||
      aliveLifeVersion(life) === undefined ||
      own(identity, "id") !== actorId ||
      typeof own(identity, "name") !== "string" ||
      typeof own(identity, "sessionId") !== "string" ||
      !Number.isSafeInteger(own(identity, "seat"))
    )
      throw new Error("mist_caster_authority_invalid");
    const privateState = own(role, "privateState");
    if (
      !privateState ||
      typeof privateState !== "object" ||
      types.isProxy(privateState) ||
      Array.isArray(privateState)
    )
      throw new Error("mist_caster_authority_invalid");
    this.role = role;
    this.campComponent = campComponent;
    this.privateState = privateState as RoleComponent["privateState"];
    this.identity = identity;
    this.identityFields = ["id", "seat", "name", "sessionId"].map((k) => own(identity, k));
    this.life = life;
    this.lifeVersion = aliveLifeVersion(life)!;
    this.binding = this.bind(own(privateState, this.key));
  }

  private factoryLife(life: AliveComponent): boolean {
    const expected = aliveLifeDescriptor(life);
    if (!expected) return false;
    const d = Object.getOwnPropertyDescriptor(life, "alive");
    return (
      !!d &&
      d.get === expected.get &&
      d.set === expected.set &&
      d.enumerable === expected.enumerable &&
      d.configurable === expected.configurable
    );
  }
  private read(raw: unknown): State | undefined {
    return this.caster === "alchemist" ? readAlchemistState(raw) : readRavenState(raw);
  }
  private bind(raw: unknown): StateBinding {
    const state = this.read(raw);
    if (!state) throw new Error("mist_caster_state_invalid");
    const names =
      this.caster === "alchemist"
        ? ["mistHistory", "healHistory"]
        : ["knownTeammateIds", "extraHistory"];
    return {
      raw: raw as State,
      expected: JSON.stringify(state),
      arrays: names.map((key) => {
        const value = own(raw, key) as unknown[];
        const rows = Array.from({ length: own(value, "length") as number }, (_value, index) =>
          own(value, String(index)),
        );
        return {
          key,
          value,
          rows,
          ...(key === "mistHistory"
            ? { nestedTargets: rows.map((row) => own(row, "targetIds")) }
            : {}),
        };
      }),
    };
  }
  isCurrent(allowFirstDeath = false): boolean {
    if (
      this.world.getComponent(this.actorId, COMPONENT.Role) !== this.role ||
      own(this.role, "role") !== this.caster ||
      own(this.role, "camp") !== this.camp ||
      this.world.getComponent(this.actorId, COMPONENT.Camp) !== this.campComponent ||
      own(this.campComponent, "camp") !== this.camp ||
      own(this.role, "privateState") !== this.privateState ||
      this.world.getComponent(this.actorId, COMPONENT.Identity) !== this.identity ||
      !["id", "seat", "name", "sessionId"].every(
        (k, i) => own(this.identity, k) === this.identityFields[i],
      ) ||
      this.world.getComponent(this.actorId, COMPONENT.Alive) !== this.life ||
      !this.factoryLife(this.life) ||
      !(this.life.alive
        ? aliveLifeVersion(this.life) === this.lifeVersion
        : allowFirstDeath && aliveLifeVersion(this.life) === this.lifeVersion + 1) ||
      own(this.privateState, this.key) !== this.binding.raw
    )
      return false;
    const value = this.read(this.binding.raw);
    return (
      !!value &&
      JSON.stringify(value) === this.binding.expected &&
      this.binding.arrays.every(
        (a) =>
          own(this.binding.raw, a.key) === a.value &&
          own(a.value, "length") === a.rows.length &&
          a.rows.every(
            (row, i) =>
              own(a.value, String(i)) === row &&
              (!a.nestedTargets || own(row, "targetIds") === a.nestedTargets[i]),
          ),
      )
    );
  }
  private current(allowFirstDeath = false): State {
    if (!this.isCurrent(allowFirstDeath)) throw new Error("mist_caster_authority_revoked");
    return this.read(this.binding.raw)!;
  }
  private install(next: State): void {
    this.current();
    const binding = this.bind(next);
    Object.defineProperty(this.privateState, this.key, {
      value: next,
      writable: true,
      enumerable: true,
      configurable: true,
    });
    this.binding = binding;
  }
  /** Paid effects/retained knowledge may be read after exactly the original body's first death. */
  state(allowFirstDeath = false): State {
    return this.current(allowFirstDeath);
  }

  /** Called once by beginNight; permission queries never invoke this transition. */
  checkRavenAtNightStart(livingWolfIds: readonly number[]): RavenState {
    if (this.caster !== "raven_claw_wolf" || this.ravenChecked)
      throw new Error("raven_night_start_reentry");
    const state = this.current() as RavenState;
    this.ravenChecked = true;
    this.install(unsealRaven(state, this.day, this.actorId, livingWolfIds));
    return this.current() as RavenState;
  }
  commitMist(targets: number[] | null, livingIds: readonly number[]): AlchemistState {
    if (this.caster !== "alchemist") throw new Error("mist_caster_kind_invalid");
    this.install(selectMist(this.current() as AlchemistState, this.day, targets, livingIds));
    return this.current() as AlchemistState;
  }
  commitSnake(target: number | null, legalTargets: readonly number[]): AlchemistState {
    if (this.caster !== "alchemist") throw new Error("mist_caster_kind_invalid");
    this.install(selectSnake(this.current() as AlchemistState, this.day, target, legalTargets));
    return this.current() as AlchemistState;
  }
  commitRavenKnife(target: number | null, livingIds: readonly number[]): RavenState {
    if (this.caster !== "raven_claw_wolf" || !this.ravenChecked)
      throw new Error("raven_night_start_required");
    this.install(
      selectRavenKnife(this.current() as RavenState, this.day, this.actorId, target, livingIds),
    );
    return this.current() as RavenState;
  }
}
